import Link from "next/link"

interface EcertificatePageProps {
  searchParams: {
    q?: string
  }
}

export default function EcertificatePage({ searchParams }: EcertificatePageProps) {
  const certificateId = searchParams.q?.trim()

  const certificateUrl = certificateId
    ? `/content/noc/NOC24/SEM2/Ecertificates/109/noc24-hs159/Course/${encodeURIComponent(certificateId)}.pdf`
    : "#"

  const isDisabled = !certificateId

  return (
    <main className="min-h-screen flex items-center justify-center bg-white">
      <div>
        <Link
          href={isDisabled ? "#" : certificateUrl}
          prefetch={false}
          className={`inline-block px-6 py-2 rounded bg-blue-600 text-white text-sm ${
            isDisabled ? "opacity-50 cursor-not-allowed pointer-events-none" : "hover:bg-blue-700"
          }`}
        >
          Course Certificate
        </Link>
      </div>
    </main>
  )
}
